import { SIMPLE_ICON_PATHS } from './simpleIconPaths'

export type TechIcon = { kind: 'path'; path: string } | { kind: 'image'; src: string }

/** "Node.js" / "NodeJS" / "node js" all collapse to "nodejs"; "#" and "+" are kept so C, C# and C++ stay distinct */
const key = (name: string) => name.toLowerCase().replace(/[\s./_-]/g, '')

// Simple Icons slugs, keyed by every spelling the data files use (paths generated by scripts/generate-icon-paths.mjs)
type Slug = keyof typeof SIMPLE_ICON_PATHS

const SIMPLE: Record<string, Slug> = {
  python: 'python',
  javascript: 'javascript',
  typescript: 'typescript',
  c: 'c',
  'c++': 'cplusplus',
  react: 'react',
  reactnative: 'react',
  nextjs: 'nextdotjs',
  nodejs: 'nodedotjs',
  expressjs: 'express',
  nestjs: 'nestjs',
  expo: 'expo',
  django: 'django',
  fastapi: 'fastapi',
  mysql: 'mysql',
  postgresql: 'postgresql',
  mongodb: 'mongodb',
  sqlite: 'sqlite',
  firebase: 'firebase',
  docker: 'docker',
  linux: 'linux',
  actions: 'githubactions',
  githubactions: 'githubactions',
  digitalocean: 'digitalocean',
  git: 'git',
  terraform: 'terraform',
  pytorch: 'pytorch',
  tensorflow: 'tensorflow',
  sklearn: 'scikitlearn',
  huggingface: 'huggingface',
  huggingfacetransformers: 'huggingface',
  langchain: 'langchain',
  langgraph: 'langgraph',
  opencv: 'opencv',
  ros: 'ros',
  vite: 'vite',
  shell: 'gnubash',
  supabase: 'supabase',
  railway: 'railway',
  cuda: 'nvidia',
  cmake: 'cmake',
  pandas: 'pandas',
  astro: 'astro',
  astrojs: 'astro',
  flutter: 'flutter',
  googlecloud: 'googlecloud',
  googlecloudplatform: 'googlecloud',
  raspberrypi: 'raspberrypi',
  googleanalytics: 'googleanalytics',
  htmlcss: 'html5',
  aspnet: 'dotnet',
  buffer: 'buffer',
}

// Brands Simple Icons no longer ships; these local files are drawn as silhouettes in the text colour
const IMAGES: Record<string, string> = {
  aws: '/icons/aws.svg',
  azure: '/icons/azure.svg',
  'c#': '/icons/csharp.svg',
  openai: '/icons/openai.svg',
  openaiapi: '/icons/openai.svg',
  pinecone: '/icons/pinecone.svg',
  langfuse: '/icons/langfuse.svg',
}

/** Monochrome icon for a technology name, if one is available */
export function iconFor(name: string): TechIcon | undefined {
  const k = key(name)
  const slug = SIMPLE[k]
  if (slug) return { kind: 'path', path: SIMPLE_ICON_PATHS[slug] }
  const image = IMAGES[k]
  return image ? { kind: 'image', src: image } : undefined
}
